import React, { useEffect, useState } from 'react';
import { useAuth, TelegramUser } from '../contexts/AuthContext';
import { useI18n } from '../contexts/I18nContext';
import { ErrorIcon, CheckIcon, LoadingIcon } from './Icons';

// Розширення window для Telegram Widget
declare global {
  interface Window {
    TelegramLoginWidget?: {
      dataOnauth: (user: TelegramUser) => void;
    };
  }
}

export const LoginPage: React.FC = () => {
  const { t } = useI18n();
  const { auth, login, clearError } = useAuth();
  const [isScriptLoaded, setIsScriptLoaded] = useState(false);
  const [loginAttempts, setLoginAttempts] = useState(0);

  // Завантаження Telegram Widget скрипта тільки в продакшн
  useEffect(() => {
    // Пропускаємо завантаження в режимі розробки
    if (process.env.NODE_ENV === 'development') {
      setIsScriptLoaded(true);
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://telegram.org/js/telegram-widget.js?22';
    script.setAttribute('data-telegram-login', 'TetraCoreBot'); // Замініть на ваш бот
    script.setAttribute('data-size', 'large');
    script.setAttribute('data-auth-url', window.location.origin + '/auth/telegram');
    script.setAttribute('data-request-access', 'write');
    script.async = true;

    script.onload = () => {
      setIsScriptLoaded(true);
    };

    // Функція для обробки авторизації
    window.TelegramLoginWidget = {
      dataOnauth: handleTelegramAuth,
    };

    document.body.appendChild(script);

    return () => {
      if (document.body.contains(script)) {
        document.body.removeChild(script);
      }
      delete window.TelegramLoginWidget;
    };
  }, []);

  const handleTelegramAuth = async (user: TelegramUser) => {
    setLoginAttempts(prev => prev + 1);
    clearError();

    const success = await login(user);
    if (!success) {
      console.error('Login failed');
    }
  };

  const handleDemoLogin = async () => {
    // Демо авторизація для розробки
    const demoUser: TelegramUser = {
      id: 123456789,
      first_name: 'Demo',
      last_name: 'User',
      username: 'demo_user',
      photo_url: 'https://via.placeholder.com/150/3b82f6/ffffff?text=DU',
      auth_date: Math.floor(Date.now() / 1000),
      hash: 'demo_hash_' + Date.now(),
    };

    await handleTelegramAuth(demoUser);
  };

  if (auth.isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-indigo-900 flex items-center justify-center">
        <div className="text-center text-white">
          <LoadingIcon size="lg" className="mx-auto mb-4 animate-spin" />
          <p className="text-xl">Перевірка авторизації...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-indigo-900 flex items-center justify-center p-4">
      <div className="max-w-md w-full">
        {/* Логотип та заголовок */}
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-20 h-20 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-2xl mb-6 shadow-2xl">
            <span className="text-2xl font-bold text-white">TC</span>
          </div>
          <h1 className="text-4xl font-bold text-white mb-2">TetraCore Hub</h1>
          <p className="text-blue-200 text-lg">Система управління потоками</p>
        </div>

        {/* Основна картка авторизації */}
        <div className="bg-white/10 backdrop-blur-lg rounded-2xl shadow-2xl border border-white/20 p-8">
          <div className="text-center mb-6">
            <h2 className="text-2xl font-semibold text-white mb-2">Вхід до системи</h2>
            <p className="text-blue-200">Авторизуйтесь через Telegram для доступу до панелі управління</p>
          </div>

          {/* Помилка авторизації */}
          {auth.error && (
            <div className="mb-6 p-4 bg-red-500/20 border border-red-500/30 rounded-xl">
              <div className="flex items-center space-x-3">
                <ErrorIcon size="sm" className="text-red-400 flex-shrink-0" />
                <div>
                  <p className="text-red-200 font-medium">Помилка авторизації</p>
                  <p className="text-red-300 text-sm">{auth.error}</p>
                </div>
              </div>
              {loginAttempts > 0 && (
                <div className="mt-3 text-red-300 text-sm">
                  Спроби входу: {loginAttempts}
                </div>
              )}
            </div>
          )}

          {/* Telegram Widget контейнер - тільки для продакшн */}
          {process.env.NODE_ENV === 'production' && (
            <div className="mb-6">
              <div className="bg-white/5 border border-white/10 rounded-xl p-6 text-center">
                {!isScriptLoaded ? (
                  <div className="flex items-center justify-center space-x-3 text-blue-200">
                    <LoadingIcon size="sm" className="animate-spin" />
                    <span>Завантаження Telegram Widget...</span>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <div className="flex items-center justify-center space-x-3 mb-4">
                      <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
                        <span className="text-white text-sm font-bold">T</span>
                      </div>
                      <span className="text-white font-medium">Telegram авторизація</span>
                    </div>

                    {/* Тут буде Telegram Widget */}
                    <div 
                      id="telegram-login-widget" 
                      className="flex justify-center"
                      dangerouslySetInnerHTML={{
                        __html: `
                          <script async src="https://telegram.org/js/telegram-widget.js?22" 
                                  data-telegram-login="TetraCoreBot" 
                                  data-size="large" 
                                  data-onauth="window.TelegramLoginWidget?.dataOnauth(user)" 
                                  data-request-access="write">
                          </script>
                        `
                      }}
                    />

                    <p className="text-blue-200 text-sm">
                      Натисніть кнопку вище для авторизації через ваш Telegram акаунт
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Інформація для режиму розробки */}
          {process.env.NODE_ENV === 'development' && (
            <div className="mb-6">
              <div className="bg-blue-500/10 border border-blue-500/20 rounded-xl p-6 text-center">
                <div className="flex items-center justify-center space-x-3 mb-4">
                  <div className="w-8 h-8 bg-blue-500 rounded-full flex items-center justify-center">
                    <span className="text-white text-sm font-bold">DEV</span>
                  </div>
                  <span className="text-white font-medium">Режим розробки</span>
                </div>
                <p className="text-blue-200 text-sm">
                  Використовуйте демо-вхід нижче для тестування системи
                </p>
              </div>
            </div>
          )}

          {/* Альтернативні варіанти */}
          <div className="space-y-4">
            {process.env.NODE_ENV === 'production' && (
              <div className="relative">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-white/20"></div>
                </div>
                <div className="relative flex justify-center text-sm">
                  <span className="px-3 bg-white/10 text-blue-200 rounded-full">або</span>
                </div>
              </div>
            )}

            {/* Демо вхід для розробки */}
            {process.env.NODE_ENV === 'development' && (
              <button
                onClick={handleDemoLogin}
                disabled={auth.isLoading}
                className="w-full py-3 px-4 bg-gradient-to-r from-amber-500 to-orange-600 text-white font-medium rounded-xl hover:from-amber-600 hover:to-orange-700 transition-all duration-300 disabled:opacity-50 disabled:cursor-not-allowed shadow-lg hover:shadow-xl"
              >
                {auth.isLoading ? (
                  <div className="flex items-center justify-center space-x-2">
                    <LoadingIcon size="sm" className="animate-spin" />
                    <span>Авторизація...</span>
                  </div>
                ) : (
                  'Демо вхід (розробка)'
                )}
              </button>
            )}
          </div>

          {/* Інформація про безпеку */}
          <div className="mt-6 p-4 bg-green-500/10 border border-green-500/20 rounded-xl">
            <div className="flex items-start space-x-3">
              <CheckIcon size="sm" className="text-green-400 flex-shrink-0 mt-0.5" />
              <div>
                <p className="text-green-200 font-medium text-sm">Безпечна авторизація</p>
                <p className="text-green-300 text-xs mt-1">
                  Ваші дані захищені шифруванням. Ми не зберігаємо ваш пароль від Telegram.
                </p>
              </div>
            </div>
          </div>
        </div>

        {/* Футер */}
        <div className="text-center mt-8 text-blue-200 text-sm">
          <p>© 2024 TetraCore Hub. Усі права захищені.</p>
          <p className="mt-1">
            Потрібна допомога? 
            <a href="#" className="text-blue-400 hover:text-blue-300 ml-1 underline">
              Зв'язатися з підтримкою
            </a>
          </p>
        </div>
      </div>
    </div>
  );
};
